alter table public.profiles add column if not exists avatar_url text;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, name, phone, avatar_url) values (new.id, coalesce(new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'full_name', ''), coalesce(new.raw_user_meta_data->>'phone', ''), coalesce(new.raw_user_meta_data->>'avatar_url', new.raw_user_meta_data->>'picture')) on conflict (id) do nothing; return new; end $$;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('avatars', 'avatars', true, 2097152, array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
drop policy if exists "avatars_read" on storage.objects;
create policy "avatars_read" on storage.objects for select using (bucket_id = 'avatars');
drop policy if exists "avatars_add" on storage.objects;
create policy "avatars_add" on storage.objects for insert to authenticated with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "avatars_remove" on storage.objects;
create policy "avatars_remove" on storage.objects for delete to authenticated using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
create table if not exists public.follows (follower uuid not null references public.profiles(id) on delete cascade, followee uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key (follower, followee), check (follower <> followee));
alter table public.follows enable row level security;
drop policy if exists "follows_read" on public.follows;
create policy "follows_read" on public.follows for select using (true);
drop policy if exists "follows_add" on public.follows;
create policy "follows_add" on public.follows for insert to authenticated with check (follower = auth.uid());
drop policy if exists "follows_remove" on public.follows;
create policy "follows_remove" on public.follows for delete to authenticated using (follower = auth.uid());
create index if not exists follows_followee_idx on public.follows (followee);
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), sender uuid not null default auth.uid() references public.profiles(id) on delete cascade, receiver uuid not null references public.profiles(id) on delete cascade, car_id uuid references public.cars(id) on delete set null, body text not null check (char_length(body) between 1 and 2000), created_at timestamptz not null default now(), read_at timestamptz, check (sender <> receiver));
alter table public.messages enable row level security;
drop policy if exists "messages_read" on public.messages;
create policy "messages_read" on public.messages for select to authenticated using (auth.uid() = sender or auth.uid() = receiver);
drop policy if exists "messages_send" on public.messages;
create policy "messages_send" on public.messages for insert to authenticated with check (sender = auth.uid());
drop policy if exists "messages_mark_read" on public.messages;
create policy "messages_mark_read" on public.messages for update to authenticated using (receiver = auth.uid()) with check (receiver = auth.uid());
revoke update on public.messages from anon, authenticated;
grant update (read_at) on public.messages to authenticated;
create index if not exists messages_receiver_idx on public.messages (receiver, created_at desc);
create index if not exists messages_sender_idx on public.messages (sender, created_at desc);
do $$ begin alter publication supabase_realtime add table public.messages; exception when duplicate_object then null; when undefined_object then null; end $$;
